payload.query:
mutation ClassroomStudentUpdate($classroomId: String!, $input: ClassroomStudentUpdateInput!) {
  classroomStudentUpdate(classroomId: $classroomId, input: $input) {
    id
    students {
      ...classroomStudentFragment
    }
  }
}

fragment classroomStudentFragment on ClassroomStudent {
  id
  invitationAccepted
  invitationCode
  name
  studentUserId
  educontUid
}
